{
  "technical_and_design_decisions": [
    "Leverage existing Hyperledger Fabric codebase and modular architecture for all implementations.",
    "For U2, follow the API and transaction format described in FAB-687 and the referenced gerrit change.",
    "For U3, implement peer upgrade using lifecycle chaincode and ensure protocol change compatibility without data loss.",
    "For U4, refactor ledger code and tests to use the new block structure while removing explicit MSP dependencies from unit tests.",
    "For U5, create visual aids (diagrams, scripts) using standard tools (e.g., PlantUML, shell scripts) to explain Fabric v1.0 architecture.",
    "For U6, maintain documentation versioning: point stable users to v0.6 docs and provide v1.0 development documentation as separate branch.",
    "For U7, add sanity checks to ensure only LCCC or normal chaincode can be invoked, rejecting other calls.",
    "For U8, design and develop Node.js SDK using Fabric's gRPC APIs, following existing SDK patterns."
  ],
  "assumptions": [
    "The developer is already familiar with Hyperledger Fabric codebase, development tools, and testing frameworks.",
    "All work is targeted at the Fabric v1.0 development branch as of sprint 6.",
    "Existing test infrastructure and CI pipeline are in place and can be reused.",
    "Effort estimates assume no major unforeseen blockers or dependencies.",
    "Documentation updates will be in English and follow existing documentation style.",
    "Node.js SDK development will use standard Node.js practices and libraries (e.g., gRPC, protobuf)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Quick Start Guide for New Visitors",
      "activity_description": "Develop a getting-started guide and onboarding materials for new users to quickly find information and start using Hyperledger Fabric, including sample code and instructions.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A2",
      "activity_name": "Document Channel Configuration Transaction",
      "activity_description": "Research and document the structure of a new-channel configuration transaction as described in FAB-687 and the referenced gerrit change, provide example format and field descriptions.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Peer Upgrade Capability",
      "activity_description": "Design and implement functionality to upgrade a peer when protocol changes occur, using lifecycle chaincode for chaincode upgrades and data migration to prevent loss. Includes testing and documentation.",
      "most_likely_effort": 44
    },
    {
      "activity_id": "A4",
      "activity_name": "Fix Ledger Code and Tests for Old Block Structure",
      "activity_description": "Identify and refactor ledger code and unit tests that still use the old block structure; remove explicit MSP dependency from ledger unit tests. Ensure all tests pass.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "Create Visual Aids and Demo Scripts for v1.0 Architecture",
      "activity_description": "Produce diagrams, visual aids, and executable scripts to explain and demonstrate the architecture and behavior of Fabric v1.0 as of end of November (sprint 6).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "Update Documentation for v1.0 Development",
      "activity_description": "Update documentation to direct users to stable v0.6 for production and provide up-to-date v1.0 documentation including usage guides and API references.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "Add Sanity Checks for Chaincode Invocation",
      "activity_description": "Implement validation logic to ensure only LCCC (Lifecycle Chaincode) or normal chaincode can be invoked, rejecting any other type of invocation as a sanity check.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A8",
      "activity_name": "Develop Node.js SDK for Fabric",
      "activity_description": "Design and implement a Node.js SDK enabling developers to interact with the blockchain network via gRPC, including transaction submission, query, and error handling. Provide tests and documentation.",
      "most_likely_effort": 68
    }
  ],
  "reported_total": {
    "most_likely_effort": 238
  }
}

